package com.chris.uberratebanner;
import android.app.*;import android.content.*;import android.graphics.BitmapFactory;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;
public class RideDetailActivity extends Activity{private RideDatabase db;private RideRecord r;@Override protected void onCreate(Bundle b){super.onCreate(b);UiKit.applySystemBars(this);db=new RideDatabase(this);r=db.get(getIntent().getLongExtra("ride_id",-1));render();}
 private void render(){ScrollView sv=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(UiKit.BG);UiKit.applySafeInsets(root,18,10,18,24);sv.addView(root);setContentView(sv);if(r==null){root.addView(UiKit.text(this,"Ride not found",20,true));return;}TextView back=UiKit.text(this,"‹  Offer Details",23,true);back.setOnClickListener(v->finish());root.addView(back);TextView rate=UiKit.text(this,String.format(Locale.US,"$%.2f/hr",r.hourly),26,true);rate.setGravity(Gravity.CENTER);rate.setTextColor(RateColors.textForHourly(this,r.hourly));rate.setPadding(dp(10),dp(12),dp(10),dp(12));rate.setBackground(UiKit.rounded(BannerUi.translucent(RateColors.forHourly(this,r.hourly)),10,this));root.addView(rate,top(16));SimpleDateFormat f=new SimpleDateFormat("EEEE, MMM d, yyyy • h:mm:ss a",Locale.getDefault());TextView when=UiKit.muted(this,f.format(new Date(r.createdAt)),12);when.setGravity(Gravity.CENTER);root.addView(when,top(7));LinearLayout d=card();field(d,"Type",r.type);field(d,"Offer",String.format(Locale.US,"$%.2f",r.payout));if("Delivery".equals(r.type)){field(d,"Uber total",r.baseTotalMinutes+" min");field(d,"Wait buffer","+"+r.deliveryBufferMinutes+" min");}else{field(d,"Pickup",r.pickupMinutes+" min");field(d,"Trip",r.tripMinutes+" min");if(r.stopCount>0){field(d,"Stops",String.valueOf(r.stopCount));field(d,"Stop buffer","+"+r.stopBufferMinutes+" min (2 min/stop)");}}field(d,"Calculated total",r.totalMinutes+" min");field(d,"Source",r.source);root.addView(d,top(14));root.addView(UiKit.text(this,"Verification image",15,true),top(14));if(r.thumbPath!=null&&new File(r.thumbPath).exists()){ImageView im=new ImageView(this);im.setAdjustViewBounds(true);im.setScaleType(ImageView.ScaleType.FIT_CENTER);im.setImageBitmap(BitmapFactory.decodeFile(r.thumbPath));im.setOnClickListener(v->{Intent i=new Intent(this,FullScreenImageActivity.class);i.putExtra("image_path",r.thumbPath);startActivity(i);});root.addView(im,top(7));TextView dl=UiKit.primaryButton(this,"Download Ride Snapshot",v->download());root.addView(dl,top(9));}else root.addView(UiKit.muted(this,"No verification image available.",12));TextView arch=UiKit.secondaryButton(this,r.archived?"Remove from Archive":"Archive Offer",v->{db.setArchived(r.id,!r.archived);r=db.get(r.id);render();});root.addView(arch,top(14));TextView del=UiKit.secondaryButton(this,"Delete Offer",v->new AlertDialog.Builder(this).setTitle("Delete this offer?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,y)->{db.delete(r.id);finish();}).show());del.setTextColor(0xFFFF6B6B);root.addView(del,top(7));}
 private void download(){try{ImageStorage.downloadRideSnapshot(this,r);Toast.makeText(this,"Saved to Downloads/RideRate",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Download failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(10),dp(14),dp(10));c.setBackground(UiKit.rounded(UiKit.SURFACE,12,this));return c;}private void field(LinearLayout c,String a,String b){LinearLayout row=new LinearLayout(this);TextView l=UiKit.muted(this,a,13),v=UiKit.text(this,b,13,true);v.setGravity(Gravity.END);row.addView(l,new LinearLayout.LayoutParams(0,-2,1));row.addView(v,new LinearLayout.LayoutParams(0,-2,1));row.setPadding(0,dp(7),0,dp(7));c.addView(row);}private int dp(int v){return UiKit.dp(this,v);}private LinearLayout.LayoutParams top(int t){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(t);return p;}@Override protected void onDestroy(){db.close();super.onDestroy();}
}
